import{_ as t,o as i,c as o,ag as a}from"./chunks/framework.DMVuHR7L.js";const s="/web-logcat/staging/docs/assets/files-default.d4gDaEyp.png",g=JSON.parse('{"title":"Files","description":"","frontmatter":{},"headers":[],"relativePath":"features/files.md","filePath":"features/files.md","lastUpdated":1778207011000}'),r={name:"features/files.md"};function l(n,e,d,p,h,c){return i(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="files" tabindex="-1">Files <a class="header-anchor" href="#files" aria-label="Permalink to &quot;Files&quot;">​</a></h1><p>The Files widget is a two-pane file browser over the <strong>ADB sync protocol</strong> — the same protocol <code>adb push</code> and <code>adb pull</code> use under the hood. Browse the device, pull files out by drag-and-drop, push files in by dropping them onto the pane.</p><p><img src="'+s+'" alt="Files tile"></p><h2 id="browsing" tabindex="-1">Browsing <a class="header-anchor" href="#browsing" aria-label="Permalink to &quot;Browsing&quot;">​</a></h2><ul><li>The <strong>left pane</strong> is a directory tree, expanding lazily as you click.</li><li>The <strong>right pane</strong> is the file listing for the focused directory, with type, size, and modification date.</li><li>The breadcrumb at the top shows the current path; click any segment to jump.</li></ul><p>The default starting path is <code>/sdcard/Download</code>. Override it in the cog modal.</p><h2 id="pulling-files-device-→-laptop" tabindex="-1">Pulling files (device → laptop) <a class="header-anchor" href="#pulling-files-device-→-laptop" aria-label="Permalink to &quot;Pulling files (device → laptop)&quot;">​</a></h2><p>Drag any file or directory from the right pane onto your operating system&#39;s file browser, the desktop, or a folder. The widget streams the file out via the sync protocol; for transfers ≥1 MB a progress bar appears in the lower-right.</p><p>You can also <strong>right-click → Pull to…</strong> to choose a destination explicitly.</p><h2 id="pushing-files-laptop-→-device" tabindex="-1">Pushing files (laptop → device) <a class="header-anchor" href="#pushing-files-laptop-→-device" aria-label="Permalink to &quot;Pushing files (laptop → device)&quot;">​</a></h2><p>Drop files (or directories) from the OS onto the right pane to push them into the focused directory. The widget queues them and streams them up, showing per-file progress. Existing files are overwritten only if you confirm.</p><h2 id="per-widget-settings" tabindex="-1">Per-widget settings <a class="header-anchor" href="#per-widget-settings" aria-label="Permalink to &quot;Per-widget settings&quot;">​</a></h2><ul><li><strong>Starting path.</strong> Where the widget mounts.</li><li><strong>Hidden files.</strong> Show / hide dot-files.</li><li><strong>Sort.</strong> Name, size, or modified time.</li></ul><h2 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to &quot;Limitations&quot;">​</a></h2><ul><li>WebUSB throughput tops out around 30–60 MB/s on USB 3 cables. Multi-GB pushes are workable but not as fast as a native <code>adb push</code>.</li><li>Android scoped-storage rules apply. App-private directories under <code>/data/data/&lt;pkg&gt;/</code> aren&#39;t readable on production builds without root.</li></ul>',15)])])}const f=t(r,[["render",l]]);export{g as __pageData,f as default};
